export const BODY: string = "\n<p>کونے گول کرنا تصویر کے تیز کونوں کو نرم کرتا ہے، جس سے تصویر جدید اور دوستانہ لگتی ہے۔ ایپ، ویب سائٹ اور سوشل میڈیا میں گول کونے عام ہیں۔</p>\n<p>گول کونے صرف سجاوٹ نہیں: وہ تصویر کو کارڈ، اوتار اور بٹن میں فٹ کرتے ہیں۔ مربع کونے سنجیدہ لگتے ہیں، گول کونے نرم اور جدید محسوس ہوتے ہیں۔</p>\n<p>یہ رہنما رداس، ہر کونے کا الگ کنٹرول، دائرہ اور گولی کی شکل، شفافیت اور فارمیٹ کی وضاحت کرتا ہے۔ کونے گول کرنے کے لیے <a href=\"/ur/tasveer-ke-kone-gol-karein/\">راؤنڈ امیج کارنرز</a> استعمال کریں۔</p>\n<h2 id=\"what-rounding-does\">کونے گول کرنا اصل میں کیا کرتا ہے</h2>\n<p>کونے گول کرنا تصویر کے چاروں کونوں کو کاٹ کر انہیں قوس کی شکل دیتا ہے۔ کٹا ہوا حصہ شفاف ہو جاتا ہے، یا ٹھوس رنگ سے بھر جاتا ہے۔</p>\n<p>گول کونے تصویر کا کوئی اہم حصہ نہیں کاٹتے، صرف کونے کا چھوٹا سا حصہ ہٹتا ہے۔ موضوع بیچ میں محفوظ رہتا ہے۔</p>\n<p>گول کونے تصویر کو نرم بناتے ہیں، اس لیے وہ اوتار اور کارڈ میں اچھے لگتے ہیں۔ سخت کونے دستاویز اور پرنٹ میں بہتر ہیں۔</p>\n<h2 id=\"radius-explained\">کونے کے رداس کی وضاحت</h2>\n<p>رداس طے کرتا ہے کہ کونہ کتنا گول ہوگا۔ چھوٹا رداس ہلکا سا گول کرتا ہے، بڑا رداس کونے کو مکمل قوس بنا دیتا ہے۔</p>\n<p>رداس تصویر کے سائز سے ملنا چاہیے: چھوٹی تصویر پر بڑا رداس تصویر کو دائرہ بنا دیتا ہے، جبکہ بڑی تصویر پر چھوٹا رداس نظر ہی نہیں آتا۔</p>\n<p>رداس کو پکسلز میں ناپا جاتا ہے۔ 20 پکسلز کا رداس چھوٹی تصویر پر واضح اور بڑی پر ہلکا لگتا ہے، اس لیے تصویر دیکھ کر رداس چنیں۔</p>\n<h2 id=\"per-corner-control\">ہر کونے کا الگ کنٹرول: ایک وقت میں ایک کونہ گول کرنا</h2>\n<p>ہر کونے کو الگ گول کیا جا سکتا ہے: صرف اوپر والے دو، یا صرف نیچے والا ایک۔ یہ کارڈ اور بینر میں کام آتا ہے، جہاں صرف ایک طرف گول کونے چاہییں۔</p>\n<p>الگ کنٹرول سے تخلیقی شکلیں بنتی ہیں، جیسے ایک کونہ گول اور باقی تیز۔ یہ ڈیزائن کو منفرد بناتا ہے۔</p>\n<p>الگ کونے گول کرتے وقت توازن دیکھیں: ایک کونہ بہت گول اور باقی تیز ہو تو تصویر بے ترتیب لگتی ہے۔</p>\n<h2 id=\"full-circle-pill\">مکمل دائرہ اور گولی کی شکل</h2>\n<p>مکمل دائرہ تصویر کو گول بنا دیتا ہے، جو پروفائل تصویر کے لیے بہترین ہے۔ گولی کی شکل لمبی تصویر کو دونوں طرف سے گول کرتی ہے، جیسے کیپسول۔</p>\n<p>دائرہ بنانے کے لیے تصویر پہلے مربع ہونی چاہیے۔ چوڑی تصویر کا دائرہ بیضوی بن جاتا ہے، جو عجیب لگتا ہے۔</p>\n<p>گولی کی شکل بینر اور بٹن میں اچھی لگتی ہے۔ لمبی تصویر کو گولی بنانے سے وہ نرم اور جدید لگتی ہے۔</p>\n<h2 id=\"transparent-vs-solid-fill\">شفاف بمقابلہ ٹھوس کونے بھرنا</h2>\n<p>شفاف بھرنے میں کٹا ہوا کونہ نظر نہیں آتا، اور اس کے پیچھے جو کچھ ہے وہ نظر آتا ہے۔ یہ ویب سائٹ اور ایپ کے لیے بہترین ہے۔</p>\n<p>ٹھوس بھرنے میں کونہ سفید یا کسی رنگ سے بھر جاتا ہے۔ یہ پرنٹ کے لیے اچھا ہے، کیونکہ کاغذ شفاف نہیں ہوتا۔</p>\n<p>شفافیت کے لیے PNG یا WebP استعمال کریں، کیونکہ JPG شفافیت نہیں بچاتا۔ JPG میں کونہ سفید ہو جاتا ہے۔</p>\n<h2 id=\"formats-png-webp-jpg\">فارمیٹ: PNG، WebP اور JPG</h2>\n<p>PNG شفافیت بچاتا ہے، اس لیے گول کونوں کے لیے بہترین ہے۔ WebP بھی شفافیت بچاتا ہے اور فائل چھوٹی دیتا ہے۔</p>\n<p>JPG شفافیت نہیں بچاتا، اس لیے اس میں کونے سفید بھر جاتے ہیں۔ اگر پس منظر سفید ہو تو JPG بھی چل جاتا ہے۔</p>\n<p>فارمیٹ چنتے وقت منزل دیکھیں: ویب کے لیے PNG یا WebP، پرنٹ کے لیے JPG بھی کافی ہے۔</p>\n<h2 id=\"rounding-for-avatars\">اوتار اور پروفائل تصویروں کے لیے کونے گول کرنا</h2>\n<p>اوتار اکثر دائرے میں دکھایا جاتا ہے، اس لیے تصویر کو پہلے مربع کاٹیں، پھر دائرہ بنائیں۔ چہرہ درمیان میں رکھیں، تاکہ دائرے میں پورا چہرہ آئے۔</p>\n<p>اوتار چھوٹا دکھائی دیتا ہے، اس لیے چہرہ بڑا ہونا چاہیے۔ کندھوں تک کا کراپ دائرے میں بہتر لگتا ہے۔</p>\n<p>اوتار کے لیے رداس مکمل رکھیں، تاکہ تصویر دائرہ بن جائے۔ آدھا گول اوتار عجیب لگتا ہے۔</p>\n<h2 id=\"rounding-for-cards\">کارڈ اور UI گرافکس کے لیے کونے گول کرنا</h2>\n<p>کارڈ میں گول کونے جدید اور نرم لگتے ہیں۔ چھوٹا رداس، جیسے 12 پکسلز، کارڈ کو پیشہ ورانہ بناتا ہے۔</p>\n<p>UI میں سب کارڈوں کا رداس ایک جیسا ہونا چاہیے، تاکہ ڈیزائن یکساں لگے۔ الگ الگ رداس ڈیزائن کو بے ترتیب بنا دیتا ہے۔</p>\n<p>کارڈ کے لیے شفافیت ضروری ہے، تاکہ کارڈ پس منظر پر درست بیٹھے۔ PNG یا WebP استعمال کریں۔</p>\n<h2 id=\"smooth-edges\">گھماؤ والے کنارے ہموار کیوں لگتے ہیں، دانے دار نہیں</h2>\n<p>گول کنارے اینٹی ایلیاسنگ سے ہموار بنتے ہیں، جو کنارے کے پکسلز کو ہلکا شفاف کر دیتا ہے۔ اس سے قوس نرم لگتی ہے، دانے دار نہیں۔</p>\n<p>بغیر اینٹی ایلیاسنگ کے گول کونے سیڑھی جیسے لگتے ہیں۔ اچھا ٹول اینٹی ایلیاسنگ خود کرتا ہے، اس لیے کنارے ہموار نکلتے ہیں۔</p>\n<p>ہموار کنارے جانچنے کے لیے تصویر کو زوم کر کے دیکھیں۔ اگر کنارہ نرم لگے تو ٹول درست ہے۔</p>\n<h2 id=\"rounding-and-print\">پرنٹ کے لیے کونے گول کرنا</h2>\n<p>پرنٹ میں گول کونے کاغذ پر کاٹے جاتے ہیں، اس لیے ڈیجیٹل گول کونے پرنٹ میں ویسے نہیں نکلتے۔ پرنٹ کے لیے گول کونے ڈیزائن میں بتائیں، فائل میں نہیں۔</p>\n<p>پرنٹ میں ٹھوس بھرنا چنیں، کیونکہ کاغذ شفاف نہیں ہوتا۔ شفاف کونے پرنٹ میں سفید نکلتے ہیں۔</p>\n<p>پرنٹ سے پہلے پرنٹر سے پوچھیں کہ وہ گول کونے کاٹ سکتا ہے یا نہیں۔ کچھ پرنٹر صرف مربع کونے دیتے ہیں۔</p>\n<h2 id=\"rounding-vs-cropping\">کونے گول کرنا بمقابلہ کراپ کرنا: الگ کام</h2>\n<p>کونے گول کرنا صرف کونے بدلتا ہے، تصویر کا حصہ نہیں ہٹاتا۔ کراپ تصویر کا حصہ ہٹاتا ہے۔ دونوں الگ کام ہیں۔</p>\n<p>پہلے کراپ کریں، پھر کونے گول کریں۔ الٹی ترتیب سے گول کونے کراپ میں کٹ سکتے ہیں۔</p>\n<p>دونوں کو ملانے سے تصویر صاف اور جدید لگتی ہے۔ کراپ فریمنگ درست کرتا ہے، گول کونے انداز دیتے ہیں۔</p>\n<h2 id=\"rounding-and-borders\">کونے گول کرنا اور بارڈر لگانا</h2>\n<p>گول کونوں پر بارڈر لگانے سے تصویر مکمل لگتی ہے۔ بارڈر بھی گول ہونا چاہیے، ورنہ وہ کونے سے باہر نکل جاتا ہے۔</p>\n<p>بارڈر کا رنگ تصویر کے رنگ سے ملنا چاہیے۔ پتلی بارڈر کافی ہے، موٹی بارڈر تصویر کو دبا دیتی ہے۔</p>\n<p>بارڈر لگانے کے بعد کونے دوبارہ جانچیں۔ اگر بارڈر کونے سے باہر ہو تو رداس بڑھائیں۔</p>\n<h2 id=\"rounding-on-mobile\">فون یا ٹیبلٹ پر کونے گول کرنا</h2>\n<p>ٹول براؤزر میں چلتا ہے، اس لیے فون پر بھی کام کرتا ہے۔ تصویر منتخب کریں، رداس چنیں اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>فون پر رداس چنتے وقت تصویر کو زوم کر کے دیکھیں، کیونکہ چھوٹی اسکرین پر رداس کا اندازہ مشکل ہوتا ہے۔</p>\n<p>فون پر کام کرتے وقت اصل فائل محفوظ رکھیں، تاکہ دوبارہ کوشش کر سکیں۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: بغیر اپ لوڈ کے کونے گول کرنا</h2>\n<p>کونے گول کرنا آپ کے براؤزر میں ہوتا ہے، تصویر کسی سرور پر نہیں جاتی۔ یہ نجی تصویروں کے لیے بہت اہم ہے۔</p>\n<p>براؤزر بند کرنے پر ڈیٹا ختم ہو جاتا ہے۔ کوئی اکاؤنٹ نہیں بنتا اور کوئی نقل محفوظ نہیں رہتی۔</p>\n<h2 id=\"common-rounding-mistakes\">کونے گول کرتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی JPG میں گول کونے بنانا ہے، جس سے کونے سفید ہو جاتے ہیں۔ شفافیت کے لیے PNG استعمال کریں۔</p>\n<p>دوسری غلطی بہت بڑا رداس چننا ہے، جس سے تصویر دائرہ بن جاتی ہے۔ تیسری غلطی چہرے کو کونے میں رکھنا ہے، جو گول کرنے پر کٹ جاتا ہے۔</p>\n<p>غلطیوں سے بچنے کے لیے رداس آہستہ بڑھائیں اور ہر قدم پر تصویر دیکھیں۔</p>\n<h2 id=\"rounding-workflow\">ایسا طریقہ جس سے کونے گول صاف رہیں</h2>\n<p>پہلے تصویر کو کراپ کریں، پھر رداس چنیں، پھر فارمیٹ چنیں اور آخر میں محفوظ کریں۔ یہ چار قدم ہر بار صاف نتیجہ دیتے ہیں۔</p>\n<p>ایک ہی منصوبے میں سب تصویروں پر ایک ہی رداس رکھیں، تاکہ ڈیزائن یکساں لگے۔</p>\n<p>طریقہ لکھ لیں اور ہر بار وہی دہرائیں۔ مستقل طریقہ وقت بچاتا ہے۔</p>\n<h2 id=\"rounding-for-stickers\">اسٹیکر اور لیبل کے لیے کونے گول کرنا</h2>\n<p>اسٹیکر میں گول کونے اچھے لگتے ہیں، کیونکہ وہ نرم اور دوستانہ محسوس ہوتے ہیں۔ اسٹیکر کا رداس درمیانہ رکھیں، تاکہ وہ کارڈ جیسا نہ لگے۔</p>\n<p>لیبل میں گول کونے پڑھنے میں آسان بناتے ہیں۔ لیبل کا متن بیچ میں رکھیں، تاکہ گول کونے اسے نہ کاٹیں۔</p>\n<p>اسٹیکر اور لیبل کے لیے PNG استعمال کریں، تاکہ شفافیت بچے۔ دائرہ اور گول کونوں کا فرق <a href=\"/ur/blog/gol-kone-vs-circle-crop/\">گول کونے بمقابلہ دائرہ کراپ</a> میں اور عملی مراحل <a href=\"/ur/blog/tasveer-ke-kone-kaise-gol-karein/\">تصویر کے کونے کیسے گول کریں</a> میں دیکھیں۔ بارڈر لگانا ہو تو <a href=\"/ur/tasveer-par-border-lagayein/\">امیج بارڈر جنریٹر</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"میرے گول کونے شفافیت کی جگہ سفید پس منظر کیوں دکھاتے ہیں؟","answer":"کیونکہ آپ نے JPG استعمال کیا ہے، جو شفافیت نہیں بچاتا۔ شفاف کونوں کے لیے PNG یا WebP استعمال کریں، تاکہ کٹا ہوا حصہ نظر نہ آئے۔"},{"question":"اپنی تصویر سے کامل دائرہ کیسے بناؤں؟","answer":"پہلے تصویر کو مربع کاٹیں، پھر رداس کو مکمل رکھیں۔ چوڑی تصویر کا دائرہ بیضوی بن جاتا ہے، اس لیے مربع کراپ ضروری ہے۔"},{"question":"کیا میں صرف اوپر والے دو کونے گول کر سکتا ہوں؟","answer":"جی ہاں، ہر کونے کا الگ کنٹرول ہے۔ صرف اوپر والے دو کونے گول کریں اور نیچے والے تیز رکھیں۔ یہ کارڈ اور بینر میں عام ہے۔"},{"question":"پروفائل تصویر کے لیے کون سا رداس استعمال کروں؟","answer":"مکمل رداس استعمال کریں، تاکہ تصویر دائرہ بن جائے۔ اوتار دائرے میں دکھایا جاتا ہے، اس لیے آدھا گول عجیب لگتا ہے۔"},{"question":"کیا کونے گول کرنے سے تصویر کا معیار کم ہوتا ہے؟","answer":"نہیں، صرف کونے کا چھوٹا سا حصہ ہٹتا ہے۔ تصویر کا مرکزی حصہ اور اس کا معیار وہی رہتا ہے۔"},{"question":"کیا میں اسکرین شاٹ کے کونے گول کر سکتا ہوں؟","answer":"جی ہاں، اسکرین شاٹ کے کونے گول کرنے سے وہ کارڈ جیسا لگتا ہے۔ PNG میں محفوظ کریں، تاکہ شفافیت بچے۔"}];
